/* hm_structs.h - Hotel Mario structures (generated by tools/structs.py) */
#ifndef HM_STRUCTS_H
#define HM_STRUCTS_H
#include "hm_types.h"

typedef struct player_t {   /* 0x1c bytes */
    int4 score;                              /* 0x000 closing a flagged door adds 50 */
    int2 hotel;                              /* 0x004 current hotel (open_level loads L<n>_*.rtf) */
    int2 stage;                              /* 0x006 stage within the hotel (0x0e = last) */
    int2 lives;                              /* 0x008 1-up item adds one, max 99 */
    int2 coins;                              /* 0x00a coin item adds one */
    int2 unk_0c;                             /* 0x00c */
    int2 power;                              /* 0x00e 0 small, 1 big (mushroom), 2 fire flower */
    int2 unk_10;                             /* 0x010 */
    int1 got_bonus;                          /* 0x012 ? set to 1/0 around stage end */
    int1 unk_13;                             /* 0x013 */
    int1 unk_14;                             /* 0x014 ? read by the save code */
    int1 unk_15;                             /* 0x015 */
    int2 progress;                           /* 0x016 ? raised, never lowered; also picks the cut-scene clip (cd_play n+7) */
    int2 unk_18;                             /* 0x018 clamped to >= 0 before a cut-scene */
    int1 unk_1a;                             /* 0x01a */
    uint1 flags;                             /* 0x01b bits 2 and 3 tested at the start of a game */
} player_t;

typedef struct obj_t {   /* 0x4c bytes */
    code *handler;                           /* 0x000 called handler(obj, gds) every frame */
    int1 unk_04[0x18];                       /* 0x004 */
    int2 unk_1c;                             /* 0x01c cleared before the init call */
    int2 unk_1e;                             /* 0x01e */
    int2 active;                             /* 0x020 ? cleared before the init call */
    int1 unk_22[0x2a];                       /* 0x022 */
} obj_t;

typedef struct mario_t {   /* 0x168 bytes */
    code *handler;                           /* 0x000 reads the pointing device: handler(path, &buttons, &x, &y) */
    code *slot[57];                          /* 0x004 compiled sprite per picture slot: slot[n](screen + x + y*384); [24] standing */
    int1 unk_0e8[0x1c];                      /* 0x0e8 */
    uint2 *door;                             /* 0x104 stage_info door/lift cell Mario is at (is_door_elev) */
    int2 step;                               /* 0x108 frame counter within a state (jump: index into jump_height) */
    int2 fcount;                             /* 0x10a counted up every field */
    int2 door_col;                           /* 0x10c column found by is_door_elev */
    int2 x;                                  /* 0x10e screen x */
    int2 y;                                  /* 0x110 screen y (floor_y - 30 when standing) */
    int2 floor;                              /* 0x112 floor 0 (top) .. 4 */
    int2 old_x;                              /* 0x114 where he was drawn last (erase position; lift: where he came from) */
    int2 old_y;                              /* 0x116 */
    int2 old_floor;                          /* 0x118 */
    int2 state_group;                        /* 0x11a state_ops row: 0 walk, 1 lift up, 2 lift down, 3 jump, 4 door, 5 win, 6 dying, 7 dead */
    int2 saved_group;                        /* 0x11c group before dying / winning */
    int2 state;                              /* 0x11e state_ops column; walk states: bit 0 = facing left */
    int2 sub;                                /* 0x120 phase of a door/lift animation */
    int2 prev_state;                         /* 0x122 walk state before a jump (bit 0 = facing left) */
    int2 anim;                               /* 0x124 picture within the walk cycle */
    int2 anim_speed;                         /* 0x126 fields per walk picture (5; 3 in hotel 3) */
    int2 anim_count;                         /* 0x128 counts down to the next picture; also the hang time at the top of a jump */
    int2 lift_used;                          /* 0x12a set after riding a lift: leave without pressing again */
    int2 lift_moved;                         /* 0x12c lift ride: Mario already moved to the other end */
    int2 jump_move;                          /* 0x12e jump: 1 = moving sideways */
    int2 unk_130;                            /* 0x130 */
    int2 unk_132;                            /* 0x132 */
    int2 jump_held;                          /* 0x134 button 1 still held since the jump began (higher jump) */
    int2 jump_hang;                          /* 0x136 hanging at the top of a high jump */
    int2 jump_skip;                          /* 0x138 short jump: skip a step on the way down */
    int2 jump_drift;                         /* 0x13a jump started from standing: drift every other field */
    int2 drift_toggle;                       /* 0x13c */
    int2 star_timer;                         /* 0x13e star item: 1000 or 7200 */
    int2 invincible;                         /* 0x140 star item sets 1 */
    int1 unk_142[4];                         /* 0x142 */
    int2 unk_146;                            /* 0x146 */
    int2 fire;                               /* 0x148 both buttons: throw a fireball (fire power) */
    int2 fire_delay;                         /* 0x14a fields before the next fireball */
    int2 throw_timer;                        /* 0x14c throwing picture shown while > 0 */
    int2 hurt_timer;                         /* 0x14e safe from enemies while > 0 (100 after a hit); flashes while > 30 */
    int2 item_flash;                         /* 0x150 items set 0x24: flashes */
    int2 cooldown[5];                        /* 0x152 counted down each field in mario_coll_det: recent coin, mushroom, flower, 1-up, star */
    int2 both_buttons;                       /* 0x15c */
    int2 down_count;                         /* 0x15e fields the stick has been held down (duck after 2) */
    int2 ready;                              /* 0x160 the_game waits for this before starting */
    int2 bumped;                             /* 0x162 walked into the screen edge (sound once) */
    int2 fell;                               /* 0x164 set when dying (exit_check ends the stage) */
    int2 hit;                                /* 0x166 set to 1 when Mario stomps or kills an enemy */
} mario_t;

typedef struct actor_t {   /* 0x274 bytes */
    code *handler;                           /* 0x000 handler(actor, gds); code lives in the L<n>_s<nn>_sub.o module */
    int2 type;                               /* 0x004 object type (>9 = enemy) */
    int2 floor;                              /* 0x006 home floor (door it lives behind) */
    int2 col;                                /* 0x008 home door column */
    int2 x;                                  /* 0x00a */
    int2 y;                                  /* 0x00c floor_y[floor] - 24 when on a floor */
    int2 cur_floor;                          /* 0x00e */
    int2 drawn_x1;                           /* 0x010 x when last drawn in plane-A buffer 1 (draw_a1) */
    int2 drawn_x0;                           /* 0x012 x when last drawn in plane-A buffer 0 (draw_a0) */
    int2 drawn_y1;                           /* 0x014 */
    int2 drawn_y0;                           /* 0x016 */
    int2 unk_018;                            /* 0x018 */
    int2 box_x0;                             /* 0x01a body box: x+9 .. x+15, y+4 .. y+23 (goomba) */
    int2 box_x1;                             /* 0x01c */
    int2 box_y0;                             /* 0x01e */
    int2 box_y1;                             /* 0x020 */
    int2 cmd;                                /* 0x022 message from the_game: 1, 2 (frame phases), 3, 4 = destroy */
    int2 dir;                                /* 0x024 0 / 1 (facing), -1 = not decided yet */
    int2 state;                              /* 0x026 row of the handler table */
    int2 step;                               /* 0x028 step within the state (walk_steps index) */
    int2 unk_02a;                            /* 0x02a */
    int2 unk_02c;                            /* 0x02c */
    int2 unk_02e;                            /* 0x02e */
    int2 appear_count;                       /* 0x030 how many more times it comes out of its door */
    int2 timer;                              /* 0x032 */
    int2 delay;                              /* 0x034 default 40 */
    int2 unk_036;                            /* 0x036 */
    int2 start_mode;                         /* 0x038 1: starts outside, 2: starts in its doorway */
    int2 frame;                              /* 0x03a index into frames[] */
    int2 unk_03c;                            /* 0x03c */
    int2 hit_x0;                             /* 0x03e hit box: x+5 .. x+19, y+9 .. y+23 (goomba) */
    int2 hit_x1;                             /* 0x040 */
    int2 hit_y0;                             /* 0x042 */
    int2 hit_y1;                             /* 0x044 */
    int2 speed;                              /* 0x046 2 (4 in hotel 8) */
    int2 unk_048;                            /* 0x048 */
    int2 unk_04a;                            /* 0x04a */
    int2 unk_04c;                            /* 0x04c */
    int2 unk_04e;                            /* 0x04e */
    code *frames[64];                        /* 0x050 compiled sprite routines: frames[frame](screen + x + y*384) */
    code *handlers[25];                      /* 0x150 handlers[state*5 + cmd](actor, gds) */
    code *walk_steps[24];                    /* 0x1b4 state 3 (walking): walk_steps[step] */
    code *steps_b[16];                       /* 0x214 */
    int4 x_min;                              /* 0x254 0x22, or 0x4c if column 0 of its floor is a lift */
    int4 x_max;                              /* 0x258 0x146, or 0x11c if column 6 of its floor is a lift */
    int1 unk_25c[0x18];                      /* 0x25c */
} actor_t;

typedef struct room_t {   /* 0x3b14 bytes */
    int2 n_actors;                           /* 0x000 */
    int2 handler_ids[25];                    /* 0x002 which module entry point each actor uses */
    struct actor_t actors[24];               /* 0x034 */
} room_t;

typedef struct gds {   /* 0x8ca bytes */
    int4 video_path;                         /* 0x000 CD-i /video device */
    int4 audio_path;                         /* 0x004 CD-i audio device */
    int4 sound_map;                          /* 0x008 sm_info() result for the sound map */
    int2 unk_00c;                            /* 0x00c */
    int2 unk_00e;                            /* 0x00e */
    int4 afx[17];                            /* 0x010 sound effect n = disc data afx[n]..afx[n+1] (playAFX) */
    int2 unk_054;                            /* 0x054 */
    int4 sound_map_no;                       /* 0x056 cd_smap() map number, starts at 5 */
    int4 fct_a;                              /* 0x05a plane A field control table (display program) */
    int4 fct_b;                              /* 0x05e plane B field control table */
    int4 lct_a;                              /* 0x062 ? plane A line control table */
    int4 lct_b;                              /* 0x066 ? plane B line control table */
    int2 video_mode;                         /* 0x06a ? 0/1: selects a 0x1e00 (20-line) offset - PAL vs NTSC? */
    int4 screen_a1;                          /* 0x06c plane A screen buffer (0x1aaac bytes) */
    int4 screen_a0;                          /* 0x070 plane A buffer, also the loading screen */
    int4 screen_b0;                          /* 0x074 plane B buffer (0x1aaac bytes) */
    int4 unk_078;                            /* 0x078 */
    int4 draw_a1;                            /* 0x07c screen_a1 + video_mode offset */
    int4 draw_a0;                            /* 0x080 screen_a0 + video_mode offset */
    int4 draw_screen;                        /* 0x084 where sprites are drawn: + x + y*384 */
    int4 unk_088;                            /* 0x088 */
    int4 clean_bg;                           /* 0x08c clean background copy used to erase sprites */
    int4 sprite_gfx;                         /* 0x090 sprite graphics for the stage */
    int4 unk_094;                            /* 0x094 */
    int4 clut_a;                             /* 0x098 colour table for plane A */
    int4 clut_b;                             /* 0x09c colour table for plane B */
    uint1 loading_clut[0x184];               /* 0x0a0 colour table for the loading screen */
    int4 bg;                                 /* 0x224 wide background image (0x29fc8 bytes) */
    int4 vram_a;                             /* 0x228 video RAM bank A (0x69520 bytes); also holds a code module */
    int4 vram_b;                             /* 0x22c video RAM bank B (0x5a632 bytes); stage module loaded here */
    int4 intro_module;                       /* 0x230 module area (vram_b + 0x1b800); main() runs it */
    int4 unk_234;                            /* 0x234 vram_b + 0x20000 */
    int4 unk_238;                            /* 0x238 demo pointer data (demoHelp_pt_coord) */
    int4 font;                               /* 0x23c font used by alphablit */
    int4 unk_240;                            /* 0x240 */
    uint1 *stage_info;                       /* 0x244 stage header: +4 ?, +8 time limit, +0x12 item table */
    room_t *room;                            /* 0x248 object table for the stage */
    int4 unk_24c;                            /* 0x24c used by puzzle_2/3 */
    mario_t *mario;                          /* 0x250 */
    struct obj_t kill_stars[5];              /* 0x254 handler kill_star */
    int2 n_fireballs;                        /* 0x3d0 fireballs in flight */
    struct obj_t fireballs[2];               /* 0x3d2 handler sm_f_ball */
    int2 frame;                              /* 0x46a frame counter */
    int2 unk_46c;                            /* 0x46c */
    int2 unk_46e;                            /* 0x46e */
    uint4 pad_buttons;                       /* 0x470 pointer device buttons (pt_coord): bit0 button 1, bit1 button 2 */
    uint4 pad_prev;                          /* 0x474 buttons last frame (edge detection) */
    int4 pad_x;                              /* 0x478 pointer x (pt_coord) */
    int4 pad_x_last;                         /* 0x47c last accepted x */
    int4 pad_y;                              /* 0x480 pointer y (pt_coord) */
    int4 pad_y_last;                         /* 0x484 last accepted y */
    int4 held_b1;                            /* 0x488 frames button 1 held */
    int4 held_b2;                            /* 0x48c frames button 2 held */
    int2 unk_490;                            /* 0x490 */
    int2 unk_492;                            /* 0x492 */
    int2 draw_field;                         /* 0x494 1/2: which of the two screen buffers is being drawn */
    int2 unk_496;                            /* 0x496 set by mario_coll_det */
    int2 unk_498;                            /* 0x498 */
    int2 unk_49a;                            /* 0x49a */
    int2 floor_y[5];                         /* 0x49c 72,108,144,180,216 */
    int2 door_x[7];                          /* 0x4a6 44,88,132,176,220,264,308 */
    int1 unk_4b4[0x74];                      /* 0x4b4 */
    int2 doors_count;                        /* 0x528 number of doors in the stage */
    int2 doors_open;                         /* 0x52a doors open now: 0 = stage cleared, doors_count = ALL DOORS OPEN */
    int4 time_left;                          /* 0x52c from stage_info+8; counts down ("TIME UP") */
    int2 unk_530;                            /* 0x530 */
    int2 unk_532;                            /* 0x532 */
    int2 unk_534;                            /* 0x534 */
    int2 unk_536;                            /* 0x536 */
    int2 unk_538;                            /* 0x538 */
    int2 unk_53a;                            /* 0x53a set to -1 at stage start */
    int2 item_hit;                           /* 0x53c item Mario just touched: 1/5 star, 2 1-up, 3 fire flower, 4 coin, 7 mushroom, 10 clear enemies, 11/12 change enemies */
    int2 item_kind;                          /* 0x53e room_eegg_init */
    int4 item_slot;                          /* 0x540 room_eegg_init: pointer into stage_info item table */
    int4 item_slot2;                         /* 0x544 room_eegg_init */
    int4 change_handler_a;                   /* 0x548 handler given to enemies by item 11 */
    int4 change_handler_b;                   /* 0x54c handler given to enemies by item 12 */
    int1 unk_550[0x46];                      /* 0x550 */
    int2 cur_player;                         /* 0x596 0 = Mario, 1 = Luigi (index into player[]) */
    int2 two_players;                        /* 0x598 ? other player still in the game */
    int2 unk_59a;                            /* 0x59a */
    int2 unk_59c;                            /* 0x59c colour cycling */
    int2 unk_59e;                            /* 0x59e colour cycling */
    int2 unk_5a0;                            /* 0x5a0 colour cycling */
    uint1 cycle_clut[0x200];                 /* 0x5a2 colour cycling buffer */
    struct player_t player[2];               /* 0x7a2 index with cur_player */
    int1 puzzle_vars[0x40];                  /* 0x7da work area shared by puzzle_2..puzzle_8 (each uses it differently) */
    int2 unk_81a;                            /* 0x81a puzzle rooms */
    int4 unk_81c;                            /* 0x81c puzzle rooms */
    int4 unk_820;                            /* 0x820 */
    int2 unk_824;                            /* 0x824 */
    int4 unk_826;                            /* 0x826 from stage_info+4 */
    int4 unk_82a;                            /* 0x82a from stage_info+4 */
    int2 unk_82e;                            /* 0x82e */
    int2 unk_830;                            /* 0x830 */
    int2 pause_ok;                           /* 0x832 ? checked by the pause signal handler */
    int4 unk_834;                            /* 0x834 init_pause */
    code *svc_cd_anim;                       /* 0x838 */
    code *svc_cd_clut;                       /* 0x83c */
    code *svc_cd_init;                       /* 0x840 */
    code *svc_cd_mul_bkg;                    /* 0x844 */
    code *svc_cd_play;                       /* 0x848 */
    code *svc_cd_smap;                       /* 0x84c */
    code *svc_cd_smq;                        /* 0x850 */
    code *svc_cd_wait;                       /* 0x854 */
    code *svc_ds_abort;                      /* 0x858 */
    code *svc_ds_close;                      /* 0x85c */
    code *svc_ds_dispatch;                   /* 0x860 */
    code *svc_ds_dispatch_execute;           /* 0x864 */
    code *svc_ds_link_map_module;            /* 0x868 */
    code *svc_ds_open;                       /* 0x86c */
    int4 svc_unk_870;                        /* 0x870 set to 0x890 (alphablit) */
    code *svc_check_doors;                   /* 0x874 */
    code *svc_color_cycle;                   /* 0x878 */
    code *svc_demoHelp_pt_coord;             /* 0x87c */
    code *svc_elev_switch;                   /* 0x880 */
    code *svc_fade;                          /* 0x884 */
    code *svc_init_doors;                    /* 0x888 */
    code *svc_init_floor_map;                /* 0x88c */
    code *svc_load_all;                      /* 0x890 */
    code *svc_player_clut_change;            /* 0x894 */
    code *svc_power_check;                   /* 0x898 */
    code *svc_power_cycle;                   /* 0x89c */
    code *svc_playAFX;                       /* 0x8a0 */
    code *svc_puzzle;                        /* 0x8a4 */
    code *svc_scoring;                       /* 0x8a8 */
    code *svc_set_up_clut;                   /* 0x8ac */
    code *svc_sfb_coll_det;                  /* 0x8b0 */
    code *svc_show_high_score;               /* 0x8b4 */
    code *svc_show_restore;                  /* 0x8b8 */
    code *svc_unfade;                        /* 0x8bc */
    int4 svc_myrtf;                          /* 0x8c0 */
    int4 svc_DsPcb;                          /* 0x8c4 */
    int2 unk_8c8;                            /* 0x8c8 */
} gds;

#endif
